import{_ as n,C as o,o as i,c as r,ag as a,E as s}from"./chunks/framework.DLWhSH9p.js";const f=JSON.parse('{"title":"Channels","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels.md","filePath":"guide/channels.md"}'),l={name:"guide/channels.md"};function c(h,e,d,u,g,p){const t=o("SchemeImage");return i(),r("div",null,[e[0]||(e[0]=a('<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>Channels are the top-level organizer in CRAFT. Each channel has its own character personality, topics, voice settings, and content library.</p><h2 id="creating-a-channel" tabindex="-1">Creating a channel <a class="header-anchor" href="#creating-a-channel" aria-label="Permalink to &quot;Creating a channel&quot;">​</a></h2><ol><li>Open the sidebar and click the <strong>channel selector</strong> inside the <strong>Studio</strong> section.</li><li>Click <strong>+ New channel</strong> at the bottom of the dropdown.</li><li>Enter a <strong>Channel name</strong> and optional <strong>Character name</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',4)),s(t,{name:"create-channel",alt:"Create Channel dialog inside the Studio channel selector"}),e[1]||(e[1]=a('<p>You&#39;ll land in the new channel&#39;s Settings so you can configure character, voice, and topics.</p><h2 id="channel-settings" tabindex="-1">Channel settings <a class="header-anchor" href="#channel-settings" aria-label="Permalink to &quot;Channel settings&quot;">​</a></h2><p>Open the <strong>channel selector</strong> in the Studio sidebar section and click <strong>Channel settings</strong>. See the full <a href="/guide/settings.html">Settings guide</a>.</p><h3 id="character" tabindex="-1">Character <a class="header-anchor" href="#character" aria-label="Permalink to &quot;Character&quot;">​</a></h3><ul><li><strong>Name</strong> — your character&#39;s display name</li><li><strong>Description</strong> — personality, tone, speaking style. This is fed to the AI for all content generation.</li><li><strong>Topics</strong> — content themes (e.g., &quot;cloud computing&quot;, &quot;DevOps&quot;, &quot;terraform&quot;). Used as default search hints in Discover.</li><li><strong>Tags</strong> — organizational labels for your ideas and scripts</li></ul><div class="tip custom-block"><p class="custom-block-title">AI Character Creator</p><p>Click <strong>Create Character</strong> in Settings to have AI generate a full character description from a few inputs: tone, audience, inspiration, and quirks.</p></div><h3 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h3><p>Configure a default TTS voice for audio generation:</p><ul><li><strong>Service</strong> — Free voice (default), ElevenLabs, or OpenAI</li><li><strong>Voice</strong> — cascading filters by language, gender, then specific voice</li><li><strong>Test</strong> — preview the voice before saving</li></ul><h3 id="niche" tabindex="-1">Niche <a class="header-anchor" href="#niche" aria-label="Permalink to &quot;Niche&quot;">​</a></h3><p>A preset (Gaming, Tech, Finance, Education, Entertainment, How-To, News, Lifestyle, Health, Food, Travel, Kids, Beauty) or <strong>Other (custom)</strong> for niches outside the preset set. Drives Discover&#39;s default search query and the RPM used to estimate earnings. Custom niches let you set a label + comma-separated Discover prompts. See <a href="/guide/settings.html#niche">Settings → Niche</a>.</p><h3 id="ai-context" tabindex="-1">AI Context <a class="header-anchor" href="#ai-context" aria-label="Permalink to &quot;AI Context&quot;">​</a></h3><p>The AI Context editor lets you view and edit the context document that shapes AI responses for this channel. In <strong>Character</strong> mode, it&#39;s auto-generated from your settings. In <strong>Raw</strong> mode, you can write custom instructions.</p><h2 id="switching-channels" tabindex="-1">Switching channels <a class="header-anchor" href="#switching-channels" aria-label="Permalink to &quot;Switching channels&quot;">​</a></h2><p>Two ways to switch:</p><ul><li><strong>Channel selector</strong> in the Studio sidebar — shows every channel you own; click to select.</li><li><strong>⌘K command palette</strong> — type a channel name, hit enter. See <a href="/guide/command-palette.html">Sidebar &amp; ⌘K</a>.</li></ul><h2 id="channel-ownership" tabindex="-1">Channel ownership <a class="header-anchor" href="#channel-ownership" aria-label="Permalink to &quot;Channel ownership&quot;">​</a></h2><p>Each channel is owned by the user who created it. You can invite collaborators from your team to work on a channel, and the marketplace lets you hire sellers to deliver work into a specific channel.</p><p>When you create a channel it&#39;s automatically assigned to you. Your account details live under the <strong>Profile</strong> menu at the bottom of the sidebar.</p><h2 id="multiple-channels" tabindex="-1">Multiple Channels <a class="header-anchor" href="#multiple-channels" aria-label="Permalink to &quot;Multiple Channels&quot;">​</a></h2><p>You can create as many channels as you need — one per YouTube channel, or separate ones for different content series.</p>',21))])}const C=n(l,[["render",c]]);export{f as __pageData,C as default};
